<template><q-page class="q-pa-lg"><div class="row items-center justify-between q-mb-lg"><div class="text-h4">Statusi narudžbi</div><q-btn color="primary" icon="add" label="Dodaj" @click="open()"/></div><q-table :rows="items" :columns="columns" row-key="id_status_narudzbe"><template #body-cell-akcije="p"><q-td :props="p"><q-btn flat icon="edit" @click="open(p.row)"/><q-btn flat color="negative" icon="delete" @click="remove(p.row)"/></q-td></template></q-table><q-dialog v-model="dialog"><q-card style="min-width:400px"><q-card-section class="text-h6">{{form.id_status_narudzbe?'Uredi':'Dodaj'}} status</q-card-section><q-card-section class="q-gutter-md"><q-input v-model="form.naziv" label="Naziv" outlined/><q-input v-model="form.opis" label="Opis" outlined/><q-input v-model.number="form.redoslijed" type="number" label="Redoslijed" outlined/><q-input v-model="form.boja" label="Boja" outlined/><q-toggle v-model="form.aktivan" label="Aktivan"/></q-card-section><q-card-actions align="right"><q-btn flat label="Odustani" v-close-popup/><q-btn color="primary" label="Spremi" @click="save"/></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>
import {onMounted,reactive,ref} from 'vue'; import {useQuasar} from 'quasar'; import {api} from 'boot/axios'; const $q=useQuasar(); const items=ref([]);const dialog=ref(false);const form=reactive({id_status_narudzbe:null,naziv:'',opis:'',redoslijed:0,boja:'',aktivan:true});const columns=[{name:'naziv',label:'Naziv',field:'naziv',align:'left'},{name:'redoslijed',label:'Redoslijed',field:'redoslijed'},{name:'boja',label:'Boja',field:'boja'},{name:'aktivan',label:'Aktivan',field:'aktivan'},{name:'akcije',label:'Akcije',field:'id_status_narudzbe'}];async function load(){items.value=(await api.get('/statusi')).data;}function open(x=null){Object.assign(form,{id_status_narudzbe:x?.id_status_narudzbe||null,naziv:x?.naziv||'',opis:x?.opis||'',redoslijed:x?.redoslijed||0,boja:x?.boja||'',aktivan:x?.aktivan!==false});dialog.value=true;}async function save(){try{if(form.id_status_narudzbe)await api.put(`/statusi/${form.id_status_narudzbe}`,form);else await api.post('/statusi',form);dialog.value=false;await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Greška pri spremanju.'});}}async function remove(x){if(!confirm(`Obrisati "${x.naziv}"?`))return;try{await api.delete(`/statusi/${x.id_status_narudzbe}`);await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Brisanje nije moguće.'});}}onMounted(load);
</script>
